import os,sys,pathlib,json,traceback,hashlib
root=pathlib.Path(os.environ['JOB_OUTPUT_DIR']);src=root/'source';src.mkdir(exist_ok=True)
FILES={'model.py': '"""Daily two-factor stochastic-arrival volatility law and price-history-only hedger."""\nimport os,json,time,math\nfrom pathlib import Path\nimport jax\njax.config.update(\'jax_enable_x64\',True)\nimport jax.numpy as jnp\nfrom jax.scipy.special import ndtr,logsumexp\nimport equinox as eqx\nimport numpy as np\nimport optax\nDT=1/252\nHORIZON=126\nBURN=0\nP_HALF={\'easy\':(3.,3.),\'base\':(3.,3.),\'hard\':(40.,3.)}\nQ_HALF={\'easy\':(3.,3.),\'base\':(40.,40.),\'hard\':(1.,40.)}\nPROB={\'easy\':0.,\'base\':1/63,\'hard\':1/63}\nCOSTS=(.0001,.0003,.001)\nLRS=(.0001,.0003,.001)\nBOUNDARIES=(0,60,180,360,600,1200,1800)\n\ndef write(path,value):\n path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)\n tmp=path.with_name(path.name+\'.tmp\');tmp.write_text(json.dumps(value,indent=2,allow_nan=False));os.replace(tmp,path)\n\ndef coefficients(half):\n a=jnp.exp(-jnp.log(2.)/jnp.asarray(half));sd=.35*jnp.sqrt(DT*(1-a*a)/(-2*jnp.log(a)))\n return a,sd\n\ndef variance(x):return jnp.minimum(.04*jnp.exp(jnp.minimum(jnp.sum(x,axis=-1),10.)),1.)\n\ndef advance(x,z,u,half,prob):\n a,sd=coefficients(half)\n return a*x+sd*z+(u<prob)[...,None]*jnp.log(2.)\n\n@eqx.filter_jit\ndef simulate(key,domain,n,measure=\'P\',days=HORIZON,burn=BURN):\n """Return causal normalized price history and latent diagnostic states separately."""\n half=(P_HALF if measure==\'P\' else Q_HALF)[domain]\n kz,ku=jax.random.split(key)\n z=jax.random.normal(kz,(burn+days,n,3));u=jax.random.uniform(ku,(burn+days,n))\n def step(carry,inputs):\n  x,log_s=carry;zz,uu=inputs\n  v=variance(x);r=-.5*v*DT+jnp.sqrt(v*DT)*zz[:,2]\n  return (advance(x,zz[:,:2],uu,half,PROB[domain]),log_s+r),(log_s,x,r)\n (last_x,last_s),(logs,states,returns)=jax.lax.scan(step,(jnp.zeros((n,2)),jnp.zeros(n)),(z,u))\n logs=jnp.concatenate((logs,last_s[None]),axis=0)\n logs=logs-logs[burn][None]\n return {\'logs\':logs,\'states\':jnp.concatenate((states,last_x[None]),axis=0),\'returns\':returns}\n\n@eqx.filter_jit\ndef integrated_variance(key,states,domain,tenor,nq):\n """Future Q jump at end of each interval; no future jump is omitted."""\n kz,ku=jax.random.split(key);z=jax.random.normal(kz,(tenor,nq,2));u=jax.random.uniform(ku,(tenor,nq))\n x=jnp.broadcast_to(states[...,None,:],states.shape[:-1]+(nq,2))\n def step(carry,inputs):\n  x,integ=carry;zz,uu=inputs\n  return (advance(x,zz,uu,Q_HALF[domain],PROB[domain]),integ+variance(x)*DT),None\n (_,integ),_=jax.lax.scan(step,(x,jnp.zeros(x.shape[:-1])),(z,u))\n return integ\n\n@eqx.filter_jit\ndef price(key,states,spot,strike,domain,tenor,nq):\n integ=integrated_variance(key,states,domain,tenor,nq)\n vol=jnp.sqrt(integ);spot=jnp.asarray(spot);strike=jnp.asarray(strike)\n d1=(jnp.log(spot/strike)[...,None]+.5*integ)/vol;d2=d1-vol\n conditional=spot[...,None]*ndtr(d1)-strike[...,None]*ndtr(d2)\n return jnp.mean(conditional,axis=-1)\n\n@eqx.filter_jit\ndef atm_iv(key,states,domain,tenor,nq):\n call=price(key,states,jnp.ones(states.shape[:-1]),jnp.ones(states.shape[:-1]),domain,tenor,nq)\n def bisect(_,bounds):\n  lo,hi=bounds;mid=(lo+hi)/2;value=2*ndtr(.5*mid*jnp.sqrt(tenor*DT))-1\n  return jnp.where(value<call,mid,lo),jnp.where(value<call,hi,mid)\n lo,hi=jax.lax.fori_loop(0,48,bisect,(jnp.zeros_like(call),jnp.ones_like(call)*3))\n return (lo+hi)/2,call\n\nclass Hedger(eqx.Module):\n gru:eqx.nn.GRUCell\n head:eqx.nn.Linear\n def __init__(self,key):\n  a,b=jax.random.split(key);self.gru=eqx.nn.GRUCell(4,32,key=a);self.head=eqx.nn.Linear(32,1,key=b)\n  self.head=eqx.tree_at(lambda m:(m.weight,m.bias),self.head,(jnp.zeros_like(self.head.weight),jnp.zeros_like(self.head.bias)))\n def __call__(self,features,hidden):\n  hidden=self.gru(features,hidden)\n  return jax.nn.sigmoid(self.head(hidden)[0]),hidden\n\n@eqx.filter_jit\ndef rollout(model,logs,cost,rule=\'learned\'):\n """No states, RV or quotes accepted: a structural observation barrier."""\n n=logs.shape[1];h=jnp.zeros((n,32));holding=jnp.zeros(n)\n def warm(hidden,t):\n  features=jnp.stack((logs[t],logs[jnp.maximum(t-1,0)],jnp.ones(n),jnp.zeros(n)),axis=1)\n  _,hidden=jax.vmap(model)(features,hidden)\n  return hidden,None\n h,_=jax.lax.scan(warm,h,jnp.arange(BURN))\n def step(carry,t):\n  hidden,old=carry;lp=logs[BURN+t];prev=logs[jnp.maximum(BURN+t-1,0)];remaining=(HORIZON-t)/HORIZON\n  features=jnp.stack((lp,prev,jnp.full(n,remaining),old),axis=1)\n  proposed,hidden=jax.vmap(model)(features,hidden)\n  if rule==\'bs\':proposed=ndtr((lp+.5*.04*(HORIZON-t)*DT)/(.2*jnp.sqrt((HORIZON-t)*DT)))\n  if rule==\'constant\':proposed=jnp.full(n,model) # not used; constant evaluated separately\n  s=jnp.exp(lp);next_s=jnp.exp(logs[BURN+t+1]);tc=cost*jnp.abs(proposed-old)*s\n  gain=proposed*(next_s-s)\n  return (hidden,proposed),(gain,tc,proposed)\n (_,holding),(gains,costs,holdings)=jax.lax.scan(step,(h,holding),jnp.arange(HORIZON))\n final_s=jnp.exp(logs[-1]);liquidation=cost*holding*final_s\n payoff=jnp.maximum(final_s-1.,0.)\n loss=payoff-jnp.sum(gains,axis=0)+jnp.sum(costs,axis=0)+liquidation\n return dict(loss=loss,gains=gains,costs=jnp.sum(costs,axis=0)+liquidation,holdings=holdings,payoff=payoff,liquidation=liquidation)\n\n@eqx.filter_jit\ndef constant_rollout(logs,cost,holding):\n s=jnp.exp(logs[BURN:]);payoff=jnp.maximum(s[-1]-1,0.)\n costs=cost*holding*(s[0]+s[-1]);loss=payoff-holding*(s[-1]-s[0])+costs\n return dict(loss=loss,costs=costs)\n\ndef risk(x):\n x=np.asarray(x);z=10*x;m=z.max();return float((m+np.log(np.mean(np.exp(z-m))))/10)\n\ndef metrics(x):\n x=np.asarray(x);return dict(entropic=risk(x),cvar95=float(np.sort(x)[int(.95*len(x)):].mean()),sd=float(x.std(ddof=1)),mse=float(np.mean(x*x)),mean=float(x.mean()))\n\n@eqx.filter_jit\ndef update(model,state,key,domain,cost,optimizer):\n key,sub=jax.random.split(key);logs=simulate(sub,domain,256)[\'logs\']\n def objective(m):return (logsumexp(10*rollout(m,logs,cost)[\'loss\'])-jnp.log(256.))/10\n value,grad=eqx.filter_value_and_grad(objective)(model)\n updates,state=optimizer.update(grad,state,eqx.filter(model,eqx.is_inexact_array))\n return eqx.apply_updates(model,updates),state,key,value,optax.global_norm(grad)\n\ndef samples(model,domain,cost,seed,count=2048,rule=\'learned\',archive=None):\n rows=[];tc=[]\n for start in range(0,count,256):\n  logs=simulate(jax.random.fold_in(jax.random.key(seed),start),domain,256)[\'logs\']\n  out=rollout(model,logs,cost,rule);rows.append(np.asarray(out[\'loss\']));tc.append(np.asarray(out[\'costs\']))\n values=np.concatenate(rows)[:count]\n if not np.isfinite(values).all():raise RuntimeError(\'nonfinite loss\')\n if archive:np.savez_compressed(archive,loss=values,cost=np.concatenate(tc)[:count])\n return values\n\ndef save_model(path,model):\n path=Path(path);tmp=path.with_name(path.name+\'.tmp\');eqx.tree_serialise_leaves(tmp,model);os.replace(tmp,path)\n\ndef train(root,arm):\n domain=\'base\' if arm==\'baseline\' else arm;root=Path(root);root.mkdir(parents=True,exist_ok=True)\n model0=Hedger(jax.random.key(20261017))\n for cost in COSTS:\n  out=root/f\'cost-{round(cost*10000)}bp\';out.mkdir(exist_ok=True);trials=[]\n  if (out/\'selection.json\').exists():continue\n  initial=risk(samples(model0,domain,cost,320261017))\n  for lr in LRS:\n   trial=out/f\'lr-{lr:g}\';trial.mkdir(exist_ok=True)\n   model=model0;optimizer=optax.chain(optax.clip_by_global_norm(1.),optax.adam(lr));state=optimizer.init(eqx.filter(model,eqx.is_inexact_array));key=jax.random.key(220261017)\n   active=0.;steps=0;best=initial;best_time=0.;history=[];compile_time=0.\n   checkpoint=trial/\'checkpoint.json\'\n   if checkpoint.exists():\n    saved=json.loads(checkpoint.read_text())\n    model,state,key_data=eqx.tree_deserialise_leaves(trial/saved[\'state_file\'],(model,state,jax.random.key_data(key)))\n    key=jax.random.wrap_key_data(key_data)\n    active=saved[\'active_seconds\'];steps=saved[\'steps\'];best=saved[\'best\'];best_time=saved[\'best_time\'];history=saved[\'history\'];compile_time=saved[\'compile_seconds\']\n    replay=risk(samples(model,domain,cost,320261017))\n    if abs(replay-history[-1][\'entropic\'])>1e-10:raise RuntimeError(\'Resume development replay mismatch\')\n    write(trial/\'resume.json\',dict(step=steps,active_seconds=active,replay_error=abs(replay-history[-1][\'entropic\'])))\n    t=time.monotonic();warm=update(model,state,key,domain,cost,optimizer);jax.block_until_ready(warm[3]);compile_time+=time.monotonic()-t\n   else:\n    save_model(trial/\'best.eqx\',model)\n    t=time.monotonic();model,state,key,value,gn=update(model,state,key,domain,cost,optimizer);jax.block_until_ready(value);compile_time=time.monotonic()-t;steps+=1\n   for boundary in BOUNDARIES[1:]:\n    if history and history[-1][\'active_seconds\']>=boundary:continue\n    with (trial/\'train.jsonl\').open(\'a\') as log:\n     while active<boundary:\n      t=time.monotonic();model,state,key,value,gn=update(model,state,key,domain,cost,optimizer);jax.block_until_ready(value);active+=time.monotonic()-t;steps+=1\n      if not np.isfinite(float(value)) or not np.isfinite(float(gn)):raise RuntimeError(\'nonfinite update\')\n      if steps%10==0:log.write(json.dumps(dict(step=steps,active_seconds=active,loss=float(value),gradient=float(gn)))+\'\\n\');log.flush()\n    score=risk(samples(model,domain,cost,320261017,archive=trial/f\'dev-{boundary}.npz\'))\n    history.append(dict(active_seconds=active,steps=steps,entropic=score))\n    save_model(trial/\'latest.eqx\',model)\n    if score<best:best=score;best_time=active;save_model(trial/\'best.eqx\',model)\n    write(trial/\'progress.json\',dict(history=history,best=best,best_time=best_time,compile_seconds=compile_time,initial=initial,lr=lr))\n    state_file=f\'state-{boundary}.eqx\';save_model(trial/state_file,(model,state,jax.random.key_data(key)))\n    write(checkpoint,dict(state_file=state_file,active_seconds=active,steps=steps,best=best,best_time=best_time,history=history,compile_seconds=compile_time))\n    # Retain the current complete boundary; checkpoint.json is the atomic commit marker.\n    for old in trial.glob(\'state-*.eqx\'):\n     if old.name!=state_file:old.unlink()\n    print(json.dumps(dict(event=\'selection\',arm=arm,cost=cost,lr=lr,**history[-1])),flush=True)\n   trials.append(dict(lr=lr,best=best,best_time=best_time,steps=steps,active_seconds=active,checkpoint=str(trial/\'best.eqx\')))\n   write(out/\'trials.json\',trials)\n  selected=min(trials,key=lambda x:x[\'best\']);(out/\'selected.eqx\').write_bytes(Path(selected[\'checkpoint\']).read_bytes())\n  write(out/\'selection.json\',dict(arm=arm,domain=domain,cost=cost,selected=selected,trials=trials,initial=initial))\n write(root/\'complete.json\',dict(status=\'complete\',arm=arm))\n', 'diagnostic.py': '"""GPU-only diagnostic and numerical gate before training."""\nfrom pathlib import Path\nimport json\nimport jax\nimport jax.numpy as jnp\nimport numpy as np\nfrom model import *\n\ndef event_paths(key,domain,n=256,days=140):\n kz,ku=jax.random.split(key);z=jax.random.normal(kz,(days,n,3));u=jax.random.uniform(ku,(days,n))\n def step(carry,inputs):\n  x,s=carry;t,zz,uu=inputs\n  # Conditional first arrival at day35. After that arrivals remain stochastic.\n  x=x+jnp.where((t==35)&(domain!=\'easy\'),jnp.log(2.),0.)\n  v=variance(x);r=-.5*v*DT+jnp.sqrt(v*DT)*zz[:,2]\n  next_x=advance(x,zz[:,:2],jnp.where(t<35,1.,uu),P_HALF[domain],PROB[domain])\n  return (next_x,s+r),(x,s,r,v)\n _,out=jax.lax.scan(step,(jnp.zeros((n,2)),jnp.zeros(n)),(jnp.arange(days),z,u))\n return out\n\ndef main(root):\n root=Path(root);root.mkdir(parents=True,exist_ok=True)\n assert jax.default_backend()==\'gpu\'\n import matplotlib\n matplotlib.use(\'Agg\')\n import matplotlib.pyplot as plt\n results={};arrays={};fig,axes=plt.subplots(1,3,figsize=(15,4.5),sharey=True)\n for ax,domain in zip(axes,(\'easy\',\'base\',\'hard\')):\n  states,logs,returns,var=eqx.filter_jit(event_paths)(jax.random.key(20261017),domain)\n  # Common Q draws give smooth comparisons; independent replicates below quantify error.\n  iv,call=atm_iv(jax.random.key(9871),states,domain,21,1024)\n  returns=np.asarray(returns);iv=np.asarray(iv);rv=np.full_like(returns,np.nan)\n  for t in range(5,140):rv[t]=np.sqrt(252*np.mean(returns[t-5:t]**2,axis=0))\n  pooled=np.sqrt(np.nanmean(rv**2,axis=1));mean_iv=iv.mean(axis=1)\n  results[domain]={str(t):dict(rv=float(pooled[35+t]),iv=float(mean_iv[35+t])) for t in (0,5,15,30,60)}\n  arrays.update({domain+\'_states\':np.asarray(states),domain+\'_logs\':np.asarray(logs),domain+\'_rv\':rv,domain+\'_iv\':iv,domain+\'_call\':np.asarray(call)})\n  ax.plot(np.arange(140)-35,pooled,label=\'Observable 5-day RV (diagnostic only)\');ax.plot(np.arange(140)-35,mean_iv,label=\'Actual rolling 21-day Q IV\')\n  ax.set(title=domain,xlabel=\'Days from conditioned first shock\');ax.grid(alpha=.2)\n axes[0].legend();fig.tight_layout();fig.savefig(root/\'stochastic_rv_iv.png\',dpi=160);plt.close(fig)\n np.savez_compressed(root/\'event_paths.npz\',**arrays)\n checks={}\n checks[\'base_rv_decay\']=results[\'base\'][\'15\'][\'rv\']<results[\'base\'][\'5\'][\'rv\']\n checks[\'base_iv_decay\']=results[\'base\'][\'15\'][\'iv\']<results[\'base\'][\'5\'][\'iv\']\n checks[\'hard_rv_above_base\']=results[\'hard\'][\'30\'][\'rv\']>results[\'base\'][\'30\'][\'rv\']+.025\n checks[\'hard_rv_above_iv\']=results[\'hard\'][\'30\'][\'rv\']>results[\'hard\'][\'30\'][\'iv\']+.015\n checks[\'hard_iv_decay\']=results[\'hard\'][\'15\'][\'iv\']<results[\'hard\'][\'0\'][\'iv\']-.02\n # Quantify future-arrival pricing contribution and MC errors at multiple maturities.\n quotes={}\n for domain in (\'easy\',\'base\',\'hard\'):\n  quotes[domain]={}\n  for tenor in (7,21,63,126):\n   estimates=np.array([float(price(jax.random.key(70000+i),jnp.zeros((1,2)),jnp.ones(1),jnp.ones(1),domain,tenor,65536)[0]) for i in range(8)])\n   se=float(estimates.std(ddof=1)/np.sqrt(8));quotes[domain][str(tenor)]=dict(price=float(estimates.mean()),replicate_se=se,nq_per_replicate=65536,replicates=8)\n   checks[f\'quote_error_{domain}_{tenor}\']=se<=.0001\n  # Horizon1 must equal BS at current variance: end-of-day arrivals affect the next interval.\n  one=float(price(jax.random.key(22),jnp.zeros((1,2)),jnp.ones(1),jnp.ones(1),domain,1,8192)[0])\n  analytic=float(2*ndtr(.1*jnp.sqrt(DT))-1)\n  checks[f\'one_day_timing_{domain}\']=abs(one-analytic)<1e-12\n  # MC convergence split independent samples and report rather than inventing exact equality.\n  prices=[float(price(jax.random.key(811+i),jnp.zeros((1,2)),jnp.ones(1),jnp.ones(1),domain,126,nq)[0]) for i,nq in enumerate((4096,16384,65536))]\n  quotes[domain][\'convergence_126\']=dict(nq=[4096,16384,65536],prices=prices)\n  checks[f\'convergence_{domain}\']=abs(prices[-1]-quotes[domain][\'126\'][\'price\'])<.0005\n  # Stock martingale under the actual bounded-variance Q process.\n  qpaths=simulate(jax.random.key(282),domain,65536,measure=\'Q\',days=21,burn=0)\n  terminal=np.exp(np.asarray(qpaths[\'logs\'][-1]));error=float(terminal.mean()-1);se=float(terminal.std(ddof=1)/np.sqrt(len(terminal)))\n  checks[f\'stock_martingale_{domain}\']=abs(error)<5*se\n  quotes[domain][\'stock_martingale_21\']=dict(error=error,se=se)\n  # Tower check: C(0,21) versus E_Q[C(1,20)] using sampled day1 states/spots.\n  step=simulate(jax.random.key(972),domain,4096,measure=\'Q\',days=1,burn=0)\n  continuation=np.asarray(price(jax.random.key(973),step[\'states\'][-1],jnp.exp(step[\'logs\'][-1]),jnp.ones(4096),domain,20,2048))\n  start=quotes[domain][\'21\'][\'price\'];tower_error=float(continuation.mean()-start);tower_se=float(continuation.std(ddof=1)/64)\n  checks[f\'option_tower_{domain}\']=abs(tower_error)<5*(tower_se+quotes[domain][\'21\'][\'replicate_se\'])+.0001\n  quotes[domain][\'option_tower_21\']=dict(error=tower_error,outer_se=tower_se,outer=4096,inner=2048)\n  # Independent raw payoff cross-check against conditional integration.\n  direct=simulate(jax.random.key(581),domain,65536,measure=\'Q\',days=126,burn=0)\n  payoff=np.maximum(np.exp(np.asarray(direct[\'logs\'][-1]))-1,0);err=float(payoff.mean()-quotes[domain][\'126\'][\'price\']);se=float(payoff.std(ddof=1)/256)\n  checks[f\'direct_payoff_{domain}\']=abs(err)<5*(se+quotes[domain][\'126\'][\'replicate_se\'])\n  quotes[domain][\'direct_payoff_126\']=dict(error=err,se=se)\n # Information barrier and exact ledger equivalence at constant initialization.\n model=Hedger(jax.random.key(20261017));paths=simulate(jax.random.key(512),\'hard\',256)\n for cost in COSTS:\n  out=rollout(model,paths[\'logs\'],cost);static=constant_rollout(paths[\'logs\'],cost,.5)\n  error=float(jnp.max(jnp.abs(out[\'loss\']-static[\'loss\'])))\n  checks[f\'ledger_{cost}\']=error<1e-12\n  checks[f\'position_bounds_{cost}\']=bool(jnp.all((out[\'holdings\']>=0)&(out[\'holdings\']<=1)))\n  # Direct pathwise cash ledger: purchase at today\'s price, liquidation at terminal price.\n  s=jnp.exp(paths[\'logs\'][BURN:]);hold=out[\'holdings\'];old=jnp.concatenate((jnp.zeros((1,256)),hold[:-1]),axis=0)\n  cash=-jnp.sum((hold-old)*s[:-1]+cost*jnp.abs(hold-old)*s[:-1],axis=0)+hold[-1]*s[-1]-cost*hold[-1]*s[-1]\n  checks[f\'cash_ledger_{cost}\']=float(jnp.max(jnp.abs(out[\'loss\']-(out[\'payoff\']-cash))))<1e-12\n checks={k:bool(v) for k,v in checks.items()}\n report=dict(status=\'passed\' if all(checks.values()) else \'failed\',checks=checks,event_summary=results,quotes=quotes,backend=jax.default_backend(),observation_audit=\'rollout signature accepts only model, price history, cost and rule; hidden states and quotes are separate\')\n write(root/\'diagnostic.json\',report);print(json.dumps(report,indent=2),flush=True)\n if not all(checks.values()):raise RuntimeError(\'stochastic numerical/economic gate failed: \'+str([k for k,v in checks.items() if not v]))\n', 'evaluate.py': '"""Paired fresh episodes and terminal/daily marked hedge diagnostics."""\nfrom model import *\n\ndef bootstrap_gain(baseline,specialist,seed=712,count=1000):\n rng=np.random.default_rng(seed);est=[]\n for _ in range(count):\n  indices=rng.integers(0,len(baseline),len(baseline));est.append(risk(baseline[indices])-risk(specialist[indices]))\n return dict(gain=risk(baseline)-risk(specialist),ci95=np.quantile(est,[.025,.975]).tolist(),resampling=\'paired whole episodes; conditional on one trained initialization\')\n\ndef main(root,models,diagnostic):\n root=Path(root);root.mkdir(parents=True,exist_ok=True)\n initial={d:diagnostic[\'quotes\'][d][\'126\'][\'price\'] for d in (\'easy\',\'base\',\'hard\')}\n result=dict(costs={},initial_premiums=initial,seed=520261017,episodes=8192,bootstrap=1000,training_seed_replicates=1)\n model0=Hedger(jax.random.key(20261017))\n # Compute hidden-state dealer marks only for evaluation, never passed into rollout.\n # Same independent subset and same marks used for every policy and transaction cost.\n daily={};quote_noise={}\n for domain in (\'easy\',\'base\',\'hard\'):\n  paths=simulate(jax.random.key(620261017),domain,256);logs=paths[\'logs\'];states=paths[\'states\'];marks=[];replicate=[]\n  for t in range(HORIZON):\n   mark=price(jax.random.fold_in(jax.random.key(848),t),states[t],jnp.exp(logs[t]),jnp.ones(256),domain,HORIZON-t,4096)\n   marks.append(np.asarray(mark))\n   if t in (0,21,63,105):\n    independent=price(jax.random.fold_in(jax.random.key(849),t),states[t],jnp.exp(logs[t]),jnp.ones(256),domain,HORIZON-t,4096)\n    replicate.append(dict(day=t,rms_independent_price_difference=float(jnp.sqrt(jnp.mean((mark-independent)**2)))))\n  marks.append(np.maximum(np.exp(np.asarray(logs[-1]))-1.,0.));marks=np.stack(marks)\n  daily[domain]=(logs,np.diff(marks,axis=0));quote_noise[domain]=replicate\n  np.savez_compressed(root/f\'daily-marks-{domain}.npz\',logs=np.asarray(logs),states=np.asarray(states),marks=marks)\n result[\'daily_quote_error\']=quote_noise\n for cost in COSTS:\n  tag=f\'cost-{round(cost*10000)}bp\';loaded={}\n  for arm in (\'baseline\',\'easy\',\'hard\'):\n   loaded[arm]=eqx.tree_deserialise_leaves(Path(models)/arm/tag/\'selected.eqx\',model0)\n  cr={}\n  for domain in (\'easy\',\'base\',\'hard\'):\n   # Own-domain fixed-hedge tuning only on development episodes.\n   candidates=np.linspace(0.,1.,41);development=[]\n   for start in range(0,2048,256):development.append(simulate(jax.random.fold_in(jax.random.key(320261017),start),domain,256)[\'logs\'])\n   scores=[]\n   for holding in candidates:\n    values=np.concatenate([np.asarray(constant_rollout(logs,cost,float(holding))[\'loss\']) for logs in development]);scores.append(risk(values))\n   fixed=float(candidates[np.argmin(scores)])\n   raw={name:[] for name in (*loaded,\'static\',\'bs\')};raw_cost={name:[] for name in raw}\n   for start in range(0,8192,256):\n    paths=simulate(jax.random.fold_in(jax.random.key(520261017),start),domain,256)\n    for name in raw:\n     out=constant_rollout(paths[\'logs\'],cost,fixed) if name==\'static\' else rollout(model0 if name==\'bs\' else loaded[name],paths[\'logs\'],cost,\'bs\' if name==\'bs\' else \'learned\')\n     raw[name].append(np.asarray(out[\'loss\'])-initial[domain]);raw_cost[name].append(np.asarray(out[\'costs\']))\n   values={name:np.concatenate(rows) for name,rows in raw.items()}\n   np.savez_compressed(root/f\'{tag}-{domain}-terminal.npz\',**values,**{k+\'_cost\':np.concatenate(v) for k,v in raw_cost.items()})\n   terminal={k:dict(**metrics(v),mean_cost=float(np.concatenate(raw_cost[k]).mean())) for k,v in values.items()}\n   # Daily marked error = option mark increment - holding*stock increment + trading cost.\n   logs,dmark=daily[domain];daily_metrics={}\n   for name in values:\n    if name==\'static\':\n     s=np.exp(np.asarray(logs));gain=fixed*np.diff(s,axis=0);daily_cost=np.zeros_like(gain);daily_cost[0]=cost*fixed*s[0];daily_cost[-1]+=cost*fixed*s[-1]\n    else:\n     out=rollout(model0 if name==\'bs\' else loaded[name],logs,cost,\'bs\' if name==\'bs\' else \'learned\');gain=np.asarray(out[\'gains\']);h=np.asarray(out[\'holdings\']);s=np.exp(np.asarray(logs));old=np.concatenate((np.zeros((1,256)),h[:-1]));daily_cost=cost*np.abs(h-old)*s[:-1];daily_cost[-1]+=np.asarray(out[\'liquidation\'])\n    error=dmark-gain+daily_cost\n    daily_metrics[name]=dict(sd=float(error.std(ddof=1)),mean=float(error.mean()),episodes=256,quote_paths=4096)\n    # The marks telescope to payoff minus the current path\'s initial mark.\n    if name!=\'static\':\n     expected=np.asarray(out[\'loss\'])-(np.maximum(s[-1]-1,0)-dmark.sum(axis=0))\n     if np.max(np.abs(error.sum(axis=0)-expected))>1e-10:raise RuntimeError(\'daily marked ledger mismatch\')\n   comparison={name:bootstrap_gain(values[\'baseline\'],v) for name,v in values.items() if name!=\'baseline\'}\n   cr[domain]=dict(terminal=terminal,daily_marked_errors=daily_metrics,baseline_minus=comparison,static_holding=fixed)\n  easy=cr[\'easy\'][\'baseline_minus\'][\'easy\'];hard=cr[\'hard\'][\'baseline_minus\'][\'hard\']\n  gate=dict(easy_useful_gain=easy[\'ci95\'][0]>.0005,hard_useful_gain=hard[\'ci95\'][0]>.0005,hard_residual_sd_above_easy=cr[\'hard\'][\'terminal\'][\'hard\'][\'sd\']>cr[\'easy\'][\'terminal\'][\'easy\'][\'sd\'])\n  cr[\'gate\']=dict(checks=gate,passed=all(gate.values()),margin=.0005)\n  result[\'costs\'][tag]=cr;write(root/\'results.partial.json\',result)\n result[\'status\']=\'complete\';write(root/\'results.json\',result);write(root/\'complete.json\',dict(status=\'complete\'))\n', 'DESIGN.md': '# Frozen stochastic volatility screen — 2026-10-18\n\nIndependent of ongoing credit campaigns. No changes to their jobs or evidence.\n\nTask: terminal replication of one short ATM European call, spot and strike 1 at issue, 126 trading days, zero rates. Stock and cash only, daily holdings constrained to [0,1], proportional transaction costs 1/3/10 bp on traded stock notional including opening and final liquidation. Terminal loss = payoff - initial Q premium - stock gains + costs. The initial premium is a fixed domain-specific shift, excluded during optimization without changing gradients/rankings. Intermediate option marks do not affect terminal wealth. Daily residual metrics use self-financing stock increments less European option mark increments when computed; otherwise daily cash trading errors must be explicitly labeled and not presented as marked hedging errors.\n\nDaily discrete model: two OU factors, eta=.35/sqrt(year), baseline variance .04; v=min(.04 exp(X1+X2),1.0). This explicit variance cap is new, keeps stock conditional variance bounded and its discounted process a true martingale. Each interval uses current factors for the stock return, then exact OU decay/noise and a simultaneous two-factor log(2) jump with Bernoulli probability 1/63. Bernoulli arrival law is part of the discrete model, not an approximation to continuous-time Poisson timing. Easy has no arrivals under either measure. Base/hard have the same positive arrival probability under P and Q; measure changes affect OU drifts only. Each stock increment has conditionally lognormal mean one. Future Q arrivals enter every option price. P half-lives easy/base=(3,3), hard=(40,3); Q half-lives easy=(3,3), base=(40,40), hard=(1,40). Measures have common shock support within each domain. Regime families differ by design.\n\nEach episode starts at option issuance, spot1 and both factors0, followed by126 trading days. The recurrent price history grows causally from issuance; there is no pre-issuance warmup. This fixes the initial Q premium within a domain and avoids silently dropping a path-dependent initial premium from the entropic objective. All arrivals are unannounced and random; there is no fixed-date event during training. Diagnostic event plots condition on no previous arrival and an arrival at day35, with ordinary future arrivals thereafter; prices still include future Q arrivals. This conditional event study is separate from unconditional training/evaluation.\n\nPolicy: same GRU32, shared initialization seed20261017 across all arms. Inputs only current normalized log price, previous log price (a causal history input), time to expiry, and previous holding. The recurrent state starts at zero at issuance. No RV, IV, option quote/premium, factor, arrival indicator, domain ID or model parameter enters the policy. Payoff/maturity are identical. No pretrained volatility estimator. Baseline samples only base; easy and hard have exactly zero mixture weight. Specialists sample only their own domains.\n\nEntropic terminal objective gamma10, batch256, Adam/global-norm clip1. Each arm and cost independently selects LR from [.0001,.0003,.001] and checkpoint [0,60,180,360,600,1200,1800] active update seconds using 2048 own-domain episodes. Initial checkpoint eligible. Three costs sequential per arm; arms concurrent on separate managed workers. One training seed220261017; own-domain development320261017. No requirement for same selected LR. Record actual updates/time and compilation separately.\n\nGate before large/adaptive follow-ups: independent paired evaluation seed520261017, 8192 episodes/domain, all three selected models, constant holding tuned on own-domain development, and causal 20% BS delta reference. Conditional whole-episode bootstrap1000; no training-seed inference. Predeclared useful entropic gain .0005 spot units on each target, requiring lower95% paired bound >.0005; hard specialist terminal loss SD must exceed easy specialist SD. Report each cost separately, no selective pooling. Failure is a result and authorizes no adaptive expansion. Numerics: Q quote replicate SE <=.0001 at initial state; martingale/tower and exact self-financing accounting checks; maturity sensitivity7/21/63/126. Event-pattern checks must pass before training. Holdouts remain unopened until selection is complete.\n\nBudget: bounded new campaign up to $20 inclusive of diagnostic, three ~4.5h training workers and final evaluation. Consumer RTX4090 cap $.60/h. Runtime limits and verified destruction apply to each rental. Existing credit spend is separate. No new packages/numerics run on control plane. Numerical source validation and all simulations execute only on rented GPUs. Source and manifests, checkpoints, raw terminal episodes, plots, metrics and environment are exported before destruction.\n'}
